CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE job_definition (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, handler_type text NOT NULL, payload_json jsonb NOT NULL DEFAULT '{}'::jsonb, schedule_cron text, timezone text NOT NULL DEFAULT 'UTC', schedule_next_at timestamptz, max_attempts int NOT NULL DEFAULT 3, timeout_sec int NOT NULL DEFAULT 60, concurrency_limit int NOT NULL DEFAULT 1, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflow (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflow_step (workflow_id uuid REFERENCES workflow(id) ON DELETE CASCADE, step_key text NOT NULL, job_definition_id uuid REFERENCES job_definition(id), depends_on text[] NOT NULL DEFAULT '{}', PRIMARY KEY(workflow_id,step_key));
CREATE TABLE workflow_run (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workflow_id uuid REFERENCES workflow(id), status text NOT NULL DEFAULT 'RUNNING', started_at timestamptz DEFAULT now(), finished_at timestamptz);
CREATE TABLE job_run (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_definition_id uuid REFERENCES job_definition(id), status text NOT NULL DEFAULT 'QUEUED', attempt int NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), locked_by text, lease_until timestamptz, idempotency_key text NOT NULL DEFAULT gen_random_uuid()::text, error text, started_at timestamptz, finished_at timestamptz, workflow_run_id uuid REFERENCES workflow_run(id), step_key text, replay_of uuid REFERENCES job_run(id));
CREATE INDEX job_run_status_run_at_idx ON job_run(status,run_at); CREATE INDEX job_run_job_running_idx ON job_run(job_definition_id,status);
CREATE TABLE worker_node (id text PRIMARY KEY, heartbeat_at timestamptz NOT NULL DEFAULT now(), current_runs int NOT NULL DEFAULT 0);
CREATE TABLE run_log (id bigserial PRIMARY KEY, run_id uuid REFERENCES job_run(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), level text NOT NULL, message text NOT NULL);
INSERT INTO job_definition(name,handler_type,payload_json,max_attempts,concurrency_limit) VALUES ('extract','sleep-and-log','{"message":"extract"}',3,2),('flaky-example','flaky','{"rate":0.5}',4,2),('load','sleep-and-log','{"message":"load"}',3,2);
INSERT INTO job_definition(name,handler_type,payload_json,max_attempts,concurrency_limit) VALUES ('transform','sleep-and-log','{"message":"transform"}',3,2),('validate','sleep-and-log','{"message":"validate"}',3,2);
INSERT INTO workflow(name) VALUES ('Extract transform validate load');
INSERT INTO workflow_step(workflow_id,step_key,job_definition_id,depends_on) SELECT w.id,'extract',j.id,'{}' FROM workflow w,job_definition j WHERE w.name='Extract transform validate load' AND j.name='extract';
INSERT INTO workflow_step(workflow_id,step_key,job_definition_id,depends_on) SELECT w.id,'transform',j.id,'{extract}' FROM workflow w,job_definition j WHERE w.name='Extract transform validate load' AND j.name='transform';
INSERT INTO workflow_step(workflow_id,step_key,job_definition_id,depends_on) SELECT w.id,'validate',j.id,'{extract}' FROM workflow w,job_definition j WHERE w.name='Extract transform validate load' AND j.name='validate';
INSERT INTO workflow_step(workflow_id,step_key,job_definition_id,depends_on) SELECT w.id,'load',j.id,'{transform,validate}' FROM workflow w,job_definition j WHERE w.name='Extract transform validate load' AND j.name='load';
